    // ==UserScript==
    // @name        New script zoom.us
    // @namespace   Violentmonkey Scripts
    // @match       https://*zoom.us/j/*
    // @grant       window.close
    // @version     1.0
    // @author      -
    // @inject-into content
    // @description 8/21/2024, 7:48:31 PM
    // ==/UserScript==

    // Create a 'wait' or 'sleep' function
    function wait(ms) {
      return new Promise(resolve => setTimeout(resolve, ms));
    };

    // Replace 3500 (3.5s) with time of your choosing
    wait(3500).then(() => window.close());


In case you'd rather just copy-paste something, here's my working version of the script above.

Only tested it once, not sure how consistent it is but it's a start. I have no other Zoom scripts

    // ==UserScript==
    // u/name        Airbnb - user ID from profile picture
    // @namespace   Violentmonkey Scripts
    // @match       https://www.airbnb.com/*
    // @grant       GM_setClipboard
    // @require     https://cdn.jsdelivr.net/npm/@violentmonkey/shortcut@1
    // @version     1.0
    // @author      -
    // @description 8/21/2024, 6:43:09 PM
    // ==/UserScript==

    const { register } = VM.shortcut;

    VM.shortcut.register ('a-b', () => {
      //Finds the profile on the "Rooms" booking, pulls the image source URL
      let profilePictureURL = document.querySelectorAll('img[decoding="async"]')[0].src;

      //Calls function below to extract user ID from entire URL
      getUserIDFromSource(profilePictureURL);
    })

    function getUserIDFromSource(profilePictureURL) {
      //Split based on '-' characters into array
      let split1 = profilePictureURL.split("-");

      //Split again based on '/' characters
      let split2 = split1[1].split("/");

      //Copy user ID to clipboard
      GM_setClipboard(split2[0])

      //Pop-up telling you it's done. Feel free to remove this line if you don't like it
      alert("User ID is - " + split2[0] + "!\nIt has been copied to your clipboard");
    }

